def transform(g):
    from collections import deque
    a=[r[:] for r in g]; H,W=len(a),len(a[0])
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            col=a[i][j]; q=deque([(i,j)]); comp=[(i,j)]; seen[i][j]=True
            while q:
                y,x=q.popleft()
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and a[ny][nx]==col:
                        seen[ny][nx]=True; comp.append((ny,nx)); q.append((ny,nx))
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
            if len(comp)==2*(h+w)-4 and h>=3 and w>=3:
                fill=7 if max(h,w)<=5 else 2
                for y in range(min(ys)+1,max(ys)):
                    for x in range(min(xs)+1,max(xs)):
                        a[y][x]=fill
    return a
